    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker = min(counts, key=counts.get)
    out = [row[:] for row in grid]

    def process(coords):
        points = [i for i, (r, c) in enumerate(coords)
                  if grid[r][c] == marker]
        # Ignore lines consisting only of isolated, scattered marks.
        if len(points) < 2:
            return
        has_cluster = any(b == a + 1 for a, b in zip(points, points[1:]))
        if not has_cluster:
            return
        for a, b in zip(points, points[1:]):
            if 1 < b - a <= 7:
                for i in range(a + 1, b):
                    r, c = coords[i]
                    if grid[r][c] == bg:
                        out[r][c] = 2

    for r in range(h):
        process([(r, c) for c in range(w)])
    for c in range(w):
        process([(r, c) for r in range(h)])
    return out
